import * as THREE from 'three/webgpu';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {string} meshUrl
 * @property {Array<{name:string,params:any}>} cinematicPrimitives
 * @property {Array<{event:string,effect:string}>} interactions
 * @property {{x:number,y:number,z:number}} position
 * @property {{x:number,y:number,z:number}} rotation
 * @property {{x:number,y:number,z:number}} scale
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>any} glbLoader
 * @property {{[key:string]:(obj:THREE.Object3D, params:any)=>void}} primitives
 * @property {(event:string)=>void} [emit]
 */

/**
 * Creates a stat‑tile node for the Collection hub.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    // Root container
    const root = new THREE.Group();

    // Load GLB (synchronous – cached)
    const gltf = ctx.glbLoader(config.meshUrl);
    const mesh = gltf.scene || gltf; // GLTF may expose .scene or be a direct Object3D
    root.add(mesh);

    // Apply placement transforms
    if (config.position) root.position.set(config.position.x, config.position.y, config.position.z);
    if (config.rotation) root.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
    if (config.scale) root.scale.set(config.scale.x, config.scale.y, config.scale.z);

    // Apply cinematic primitives
    if (Array.isArray(config.cinematicPrimitives)) {
        for (const prim of config.cinematicPrimitives) {
            const fn = ctx.primitives[prim.name];
            if (typeof fn === 'function') {
                fn(root, prim.params);
            }
        }
    }

    // --------------------------------------------------------------------
    // Interaction handling (hover rise‑in, click emit)
    // --------------------------------------------------------------------
    const hoverAnim = gsap.timeline({ paused: true, defaults: { ease: 'power3.out' } });
    const riseAmount = 0.15; // scene units as per spec
    hoverAnim.to(root.position, { y: '+=' + riseAmount, duration: 0.15 });

    // Handlers container attached to userData
    root.userData.handlers = {
        // Expected to be called by the surrounding system on hover start
        hoverEnter: () => {
            hoverAnim.play();
        },
        // Expected to be called on hover end
        hoverLeave: () => {
            hoverAnim.reverse();
        },
        click: () => {
            if (typeof ctx.emit === 'function') {
                ctx.emit('hub-collection.select');
            }
        }
    };

    // Optional: expose data binding metadata (no runtime effect)
    root.userData.bindings = [
        {
            source: 'form.email',
            target: 'trpc.waitlist.join.input.email'
        }
    ];

    // --------------------------------------------------------------------
    // Cleanup
    // --------------------------------------------------------------------
    root.userData.cleanup = () => {
        // Dispose geometries & materials
        root.traverse((child) => {
            if (child.isMesh) {
                if (child.geometry) child.geometry.dispose();
                if (Array.isArray(child.material)) {
                    child.material.forEach((mat) => mat && mat.dispose && mat.dispose());
                } else if (child.material && child.material.dispose) {
                    child.material.dispose();
                }
            }
        });

        // Kill GSAP timeline
        hoverAnim.kill();
    };

    return root;
}
